        "pass": "Yes when the run wrote PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "The longer sign-in is pointed out",
      "source": "format",
      "judged": {
        "question": "Does PR.md tell the reviewer that people now stay signed in for 60 minutes, not 20?",
        "pass": "Yes when it names both numbers, or says the session grows to an hour.",
        "fail": "No when the new session length is not mentioned.",
        "examples": {
          "pass": [
            "Sessions now last 60 minutes (were 20)."
          ],
          "fail": [
            "Small config tweak."
          ]
        }
      }
    },
    {
      "text": "The new config file is named",
      "source": "format",
      "judged": {
        "question": "Does PR.md say the session length now comes from config/session.toml?",
        "pass": "Yes when it names that file as the place the length is set.",
        "fail": "No when the file is left out.",
        "examples": {
          "pass": [
            "The length is read from `config/session.toml`."
          ],
          "fail": [
            "A PR.md about the 60 minutes only."
          ]
        }
      }
    }
  ]
}

